pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Set owner to a known address so we can prank as the owner
        vm.prank(address(this));
        c.transferOwnership(address(this));
    }
    function testFuzz_property(address caller) public {
        // caller is fuzzed; we only care about when caller is the owner
        vm.assume(caller == c.owner());
        vm.prank(caller);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

